                            ImGui::TableSetupScrollFreeze(0, 1);
                            ImGui::TableSetupColumn("Stage", ImGuiTableColumnFlags_WidthFixed,
                                                    62.0f * scale);
                            ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed,
                                                    150.0f * scale);
                            ImGui::TableSetupColumn("Expected return");
