                                if (correlation.apiIndex >= crackmeTriage_.apis.size()) continue;
                                const CrackmeTriageApiEvidence& api =
                                    crackmeTriage_.apis[correlation.apiIndex];
                                const NetworkReturnFlow* flow = triageReturnFlowForCorrelation(
                                    crackmeTriage_, selectedTrail, correlation);
                                const auto contract = LookupNetworkApiReturnContract(
                                    api.dll, api.canonicalName);
                                ImGui::TableNextRow();
                                ImGui::PushID((int)index);
                                ImGui::TableNextColumn();
                                ImGui::TextDisabled("%s", NetworkStageText(correlation.stage));
