                        ImGui::TableSetColumnIndex(1); ImGui::TextDisabled("%lluK", (unsigned long long)(m.size / 1024));
                        ImGui::TableSetColumnIndex(2);
                        LoadedModule* rm = ctx.modules.byBase(m.base);
