                ImGui::RenderTextEllipsis(ImGui::GetWindowDrawList(), at,
                    ImVec2(at.x + width, at.y + ImGui::GetTextLineHeight()),
                    at.x + width, at.x + width, status.c_str(), nullptr, nullptr);
                ImGui::Dummy(ImVec2(width, ImGui::GetTextLineHeight()));
